"""A2A server for the "data-sourcing-agent" agent (generated by genproj).

Run it with:

    uvicorn agent.main:app --host 0.0.0.0 --port 8700

The A2A app, agent card and JSON-RPC transport come from the **official
a2a-sdk** (`a2a.server`); this module wires a Pydantic AI agent into it. Startup
self-registration with the LiteLLM gateway lives in agent/register.py.

Why a2a-sdk and not FastA2A: the LiteLLM gateway invokes this agent with an
a2a-sdk 1.1.0 client, and FastA2A 2.0.1 could not be spoken to by it - its card
declared a "1.0" interface while the server only spoke the 0.3 wire, and its
`result.task` envelope was unparseable by the client. Using the same SDK on both
sides of the wire removes the skew by construction. `a2a-sdk` is pinned to the
gateway's client version (pyproject).

Bind 0.0.0.0, not 127.0.0.1: the caller is the LiteLLM proxy reaching this
container across the network, so a loopback bind is unreachable.
"""

from __future__ import annotations

import json
import os
from contextlib import asynccontextmanager
from pathlib import Path

from a2a.helpers.proto_helpers import new_task_from_user_message, new_text_part
from a2a.server.agent_execution import AgentExecutor, RequestContext
from a2a.server.events.event_queue import EventQueue
from a2a.server.request_handlers import DefaultRequestHandler
from a2a.server.routes import create_agent_card_routes, create_jsonrpc_routes
from a2a.server.tasks import InMemoryTaskStore
from a2a.server.tasks.task_store import TaskStore
from a2a.server.tasks.task_updater import TaskUpdater
from pydantic_ai import Agent, ModelSettings, PromptedOutput
from pydantic_ai.mcp import MCPToolset
from starlette.applications import Starlette
from starlette.middleware import Middleware
from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.routing import Route

from agent.card import AGENT_SKILLS, build_agent_card
from agent.contract import validate_agent_result
from agent.gate import (
    DEFAULT_POLICY,
    EnforcementOutcome,
    GateAction,
    GateState,
    ask_cost_gate,
    ask_gate,
    enforce,
    record,
    serialise_state,
    should_retain_state,
)
from agent.gatelog import (
    append_records,
    build_records,
    default_thresholds,
    new_request_id,
)
from agent.headers import capture_litellm_headers
from agent.history import TaskHistory, build_task_store
from agent.intent import NON_REQUEST_REPLY, is_data_request
from agent.interpret import (
    ParsedIntent,
    build_interpreter,
    ticket_prompt,
    to_gate_state,
)
from agent.jev import JevClient
from agent.model import build_model
from agent.register import register_with_litellm
from agent.roost import RoostBridge
from agent.ticket import TicketProposal, render_ticket_yaml

PACKAGE_ROOT = Path(__file__).resolve().parent
INSTRUCTIONS_PATH = PACKAGE_ROOT.parent / "prompts" / "instructions.md"

AGENT_NAME = "data-sourcing-agent"
AGENT_DESCRIPTION = "Turns a fuzzy market-data need into a validated, costed Databento download ticket (requests/*.yaml) for human sign-off. Drafts only: it cannot spend credit, cannot approve a request, and is not the authority on whether a request is legal - a deterministic validator asks the Databento API. Covers Databento historical US equities, futures and options datasets."
# The wire the a2a-sdk JSON-RPC endpoint speaks. The SDK's native server is the
# "1.0" wire (`SendMessage`), and the same value is registered with LiteLLM. The
# endpoint also enables the SDK's v0.3 compatibility layer (see create_app), so
# a legacy `message/send` caller still works - but the card advertises 1.0, which
# is what the SDK server natively speaks.
PROTOCOL_VERSION = "1.0"
# The URL the card advertises — the address the LiteLLM proxy DIALS, from its
# own vantage on `ai_proxy`. `0.0.0.0` is a *bind* address: the proxy reading it
# would dial itself, so registration would succeed and invocation would fail.
# The container's own name on `ai_proxy` is what the proxy's embedded DNS
# resolves, so that is the default. See the handover memo §4.
CARD_URL = os.environ.get("A2A_CARD_URL", "http://data-sourcing-agent:8700")


# What the door says when it actually stops a request. These are only ever reached
# when `GatePolicy.enforce` is true — in observe-only nothing routes on the gate, so
# a turn that would have been stopped runs exactly as before (gate memo §5).
_ENFORCED_REPLY = {
    GateAction.reject: (
        "I can't take this request: it falls outside what this agent may do "
        "(sourcing historical Databento market data). Nothing was priced or drafted."
    ),
    GateAction.ask_clarifying: (
        "I need one more thing before I can price this — the request leaves an axis "
        "(dataset, schema, universe, or timeframe) to guess, or asks for a spend out "
        "of proportion to the ask. Tell me the missing detail (or the budget) and I'll "
        "produce the ticket."
    ),
}


def _enforced_reply(outcome: EnforcementOutcome | None) -> str | None:
    """The message to complete a turn with, or None to carry on.

    None in every observe-only case: `enforce()` already returns `proceed` unless the
    policy is enforcing, so this is the single point where "the gate decided" becomes
    "the turn changed". Kept next to the executor so the routing decision and the
    wording it produces live together.
    """
    if outcome is None or outcome.action is GateAction.proceed:
        return None
    return _ENFORCED_REPLY.get(outcome.action)


def _load_instructions() -> str:
    """The agent's instructions, read fresh from prompts/instructions.md.

    That file is human-owned: genproj seeds it once and regeneration never
    overwrites it, so instruction changes do not require regeneration.
    """
    if INSTRUCTIONS_PATH.exists():
        return INSTRUCTIONS_PATH.read_text(encoding="utf-8")
    return "You are the front desk for Databento historical downloads. Turn a human's intent into a draft download ticket. You never mark a ticket approved, never raise cost.max_usd, and never declare a request valid or a cost known - the deterministic Validator asks the Databento API, and only a human signs off on spend. `stype_in` is one of raw_symbol, parent, continuous, instrument_id, and you must not guess it. `why` is mandatory."


AGENT_TOOLSETS = [
    MCPToolset("http://mcphub:3000/mcp/databento-discovery"),
]

agent = Agent(
    build_model(),
    instructions=_load_instructions(),
    # `PromptedOutput`, NOT the default `ToolOutput`: `deepseek-v4-flash` is a
    # thinking model and refuses a forced `tool_choice` ("Thinking mode does not
    # support this tool_choice"), and the gateway's provider rejects a
    # `json_schema` response_format ("This response_format type is unavailable
    # now"). PromptedOutput asks for JSON in the prompt and parses it — verified
    # to round-trip on this alias (handover memo §5.1). `NativeOutput` fails; do
    # not "upgrade" to it without re-testing.
    output_type=PromptedOutput(TicketProposal),
    # Reasoning tokens bill against `max_tokens` on this model, so a low cap
    # truncates the answer before it is emitted. The default is too small.
    model_settings=ModelSettings(max_tokens=4096),
    retries={"output": 3},
    toolsets=AGENT_TOOLSETS,
)
# The Validator layer. It runs on every model output; on failure it raises
# ModelRetry with real error text, up to `retries["output"]` times.
agent.output_validator(validate_agent_result)

# The interpretation step, pulled out of the run so the gate can sit after it
# (memo `jev-integration-v1` §3.1; decided 2026-10-06). It shares the gateway
# model and the discovery toolset with the ticket run.
interpreter = build_interpreter(build_model(), toolsets=AGENT_TOOLSETS)
# The Jev client, reached through the proxy's native `/typesafe` route. Held here
# (not in the Validator) — the boundary rule the gate tests enforce.
jev_client = JevClient.from_env()


async def healthz(_: Request) -> JSONResponse:
    """Liveness for the container healthcheck and the Homepage widget."""
    return JSONResponse({"status": "ok"})


async def _register() -> None:
    """Register this agent's card with the LiteLLM gateway, once, at startup."""
    await register_with_litellm(
        agent_name=AGENT_NAME,
        card_url=CARD_URL,
        protocol_version=PROTOCOL_VERSION,
        description=AGENT_DESCRIPTION,
        skills=AGENT_SKILLS,
    )


class TicketAgentExecutor(AgentExecutor):
    """Runs the Pydantic AI agent for one A2A request and returns its ticket.

    The SDK calls `execute` with the request's `RequestContext` (which carries
    the user message and the `ServerCallContext`) and an `EventQueue` to publish
    events on. We publish a working status, run the agent, publish the rendered
    ticket as an artifact, and complete.

    The request headers reach `current_litellm_headers()` here: the SDK's
    default context builder records them in `call_context.state['headers']`, and
    `capture_litellm_headers` puts them in the context variable that
    `HeaderForwardingClient` injects on the agent's own model calls.
    """

    def __init__(
        self,
        agent: Agent,
        roost_bridge: RoostBridge | None = None,
        interpreter: Agent | None = None,
        jev: JevClient | None = None,
    ):
        self._agent = agent
        # The fleet hub. A no-op bridge when roost is unconfigured, so this
        # class never has to branch on whether roost is on (fail-open).
        self._roost = roost_bridge or RoostBridge()
        # The interpretation step and the gate. Both optional: when unset the
        # turn runs exactly as before, which is how the tests drive this class
        # without a model or a gateway.
        self._interpreter = interpreter
        self._jev = jev

    async def _assess(
        self, user_input: str, request_id: str
    ) -> tuple[ParsedIntent | None, EnforcementOutcome | None]:
        """Interpret, then gate — observe-only. Returns the reading and the outcome.

        Best-effort by design: the gate is advisory and fail-open, so a failure
        here — the interpreter, Jev, assembly — must not alter the turn's
        outcome. It logs the *computed* action; nothing routes on it until
        `GatePolicy.enforce` is true (memo `jev-integration-v1` §3).

        The returned `ParsedIntent` is what lets the ticket step stop re-reading
        the prose: the reading is done once, here, and handed on. The
        `EnforcementOutcome` is what the caller routes on — `proceed` for as long
        as the policy is observe-only.
        """
        if self._interpreter is None:
            return None, None
        try:
            intent = (await self._interpreter.run(user_input)).output
        except Exception as exc:  # a bad reading is not a failed turn
            print(f"[interpret] skipped: {exc!r}", flush=True)
            return None, None
        if self._jev is None:
            return intent, None
        try:
            state = to_gate_state(user_input, intent)
            answers, decision = await ask_gate(self._jev, state)
            outcome = enforce(decision, request_id, DEFAULT_POLICY)
            # Retain the observe-only traffic — this IS the gate's value until
            # it enforces anything (gate memo §3/§5).
            self._log_gate(state, answers, decision, request_id, outcome)
            print(f"[gate] observe-only: {record(decision)} -> {outcome.reason}", flush=True)
            return intent, outcome
        except Exception as exc:  # the gate must never break the turn
            print(f"[gate] skipped: {exc!r}", flush=True)
            return intent, None

    async def _assess_cost(
        self,
        user_input: str,
        intent: ParsedIntent | None,
        ticket: object | None,
        request_id: str,
    ) -> EnforcementOutcome | None:
        """The post-price checkpoint: fire D5 once the Validator has priced the request.

        The front door runs before pricing, so D5 ("is this spend proportionate?")
        is not answerable there and is absent from the first question set. Once the
        ticket step has produced an estimate, the question becomes answerable and is
        asked here — D5 alone, on the same `request_id`, so the two checkpoints of a
        turn join in the log (memo `jev-integration-v1` §3).

        Observe-only and best-effort, exactly like the front door: it logs the
        action and never routes on it, and any failure is swallowed so it cannot
        change the turn's outcome.
        """
        if self._jev is None:
            return None
        try:
            estimate = getattr(getattr(ticket, "cost", None), "estimate_usd", None)
            if intent is not None:
                state = to_gate_state(user_input, intent, estimate_usd=estimate)
            else:
                # No reading (interpreter absent or failed), but there is still a
                # priced request worth judging: assemble the state from what we have.
                state = GateState(
                    raw_request=user_input, parsed_intent="(not parsed)", estimate_usd=estimate
                )
            answers, decision = await ask_cost_gate(self._jev, state, estimate)
            outcome = enforce(decision, request_id, DEFAULT_POLICY)
            self._log_gate(state, answers, decision, request_id, outcome)
            print(f"[gate:cost] observe-only: {record(decision)} -> {outcome.reason}", flush=True)
            return outcome
        except Exception as exc:  # the cost checkpoint must never break the turn
            print(f"[gate:cost] skipped: {exc!r}", flush=True)
            return None

    def _log_gate(
        self,
        state,
        answers,
        decision,
        request_id: str,
        outcome: EnforcementOutcome | None = None,
    ) -> None:
        """Retain one checkpoint's traffic — the gate's value until it enforces (§3/§5).

        The *effective* action is recorded alongside the computed one, and the
        holdback flag with it, so the log distinguishes "the door stopped this"
        from "the door would have stopped this and the holdback admitted it" — the
        distinction the enforcement-bias analysis rests on (§6.6). The raw `state`
        is retained for anything the door would stop, so the rejected region can be
        audited later.
        """
        retain = should_retain_state(decision)
        append_records(
            build_records(
                serialise_state(state),
                answers,
                decision,
                thresholds=default_thresholds(
                    DEFAULT_POLICY.d1_cut, DEFAULT_POLICY.d2_cut, DEFAULT_POLICY.d5_cut
                ),
                request_id=request_id,
                action_taken=outcome.action.value if outcome is not None else None,
                holdback=bool(outcome and outcome.holdback),
                retain_state=retain,
            )
        )

    async def execute(self, context: RequestContext, event_queue: EventQueue) -> None:
        # The a2a-sdk event pipeline requires the Task to be enqueued before any
        # status/artifact update (otherwise the consumer raises
        # InvalidAgentResponseError). On a fresh request we mint it from the user
        # message; on a follow-up the framework hands us the stored task.
        initial_task = context.current_task
        if initial_task is None and context.message is not None:
            initial_task = new_task_from_user_message(context.message)
        if initial_task is not None:
            await event_queue.enqueue_event(initial_task)

        updater = TaskUpdater(event_queue, context.task_id, context.context_id)
        await updater.start_work()
        capture_litellm_headers(context.call_context.state.get("headers"))
        # Reflect the turn in the roost fleet. The counters/emits are best-effort
        # and never await the model, so a long turn cannot make the hub's
        # `status.get` poll time out (which is what would drop the tunnel).
        self._roost.turn_started()
        await self._roost.emit("turn_started", taskId=context.task_id)
        try:
            user_input = context.get_user_input()
            # A turn that is not a data request (a greeting, thanks, small talk)
            # has no `TicketProposal` to make. Forcing it through
            # `PromptedOutput(TicketProposal)` is what produced the two observed
            # failures: output retries exhausted (TASK_STATE_FAILED) or a
            # fabricated placeholder ticket. Answer it conversationally instead,
            # before the model runs, and leave the ticket path untouched for
            # real requests. The check is deterministic; see agent/intent.py.
            if not is_data_request(user_input):
                await updater.complete(
                    updater.new_agent_message([new_text_part(NON_REQUEST_REPLY)])
                )
                return
            # Interpret, then gate — observe-only, so this cannot change the turn.
            # The reading seeds the ticket step so it does not re-derive the axes.
            # One request id spans both gate checkpoints (front door, then post-price).
            request_id = new_request_id()
            intent, outcome = await self._assess(user_input, request_id)
            # Only ever non-None when the policy is enforcing (GatePolicy.enforce);
            # in observe-only the effective action is always `proceed` (gate memo §5).
            stopped = _enforced_reply(outcome)
            if stopped is not None:
                await updater.complete(updater.new_agent_message([new_text_part(stopped)]))
                return
            prompt = ticket_prompt(user_input, intent) if intent is not None else user_input
            result = await self._agent.run(prompt)
            ticket = result.output
            # The post-price checkpoint: D5 could not be asked at the front door
            # (no estimate yet). Now that the Validator has priced the request, it
            # can be — observe-only, same request id.
            cost_outcome = await self._assess_cost(user_input, intent, ticket, request_id)
            stopped = _enforced_reply(cost_outcome)
            if stopped is not None:
                await updater.complete(updater.new_agent_message([new_text_part(stopped)]))
                return
            rendered = render_ticket_yaml(ticket)
        except Exception as exc:  # a failed turn is a failed task, not a crash
            await updater.failed(
                updater.new_agent_message([new_text_part(f"The run failed: {exc}")])
            )
            return
        finally:
            self._roost.turn_finished()
            await self._roost.emit("finished", taskId=context.task_id)
        await updater.add_artifact([new_text_part(rendered)], name="ticket")
        await updater.complete()

    async def cancel(self, context: RequestContext, event_queue: EventQueue) -> None:
        updater = TaskUpdater(event_queue, context.task_id, context.context_id)
        await updater.cancel()


class A2AVersionHeaderMiddleware:
    """Supply the `A2A-Version` header the SDK dispatcher validates.

    The SDK's dispatcher rejects a request whose `A2A-Version` header disagrees
    with the dialect it routed to, and treats a *missing* header as "0.3". The
    a2a-sdk client sets the header, but a client that omits it (or a raw probe)
    would be rejected on the 1.0 path. So when the header is absent we supply
    the version that matches the JSON-RPC method: the v0.3 methods are the ones
    with a `/` in them (`message/send`), everything else is 1.0 (`SendMessage`).
    An explicit header is never overridden.
    """

    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope.get("type") != "http":
            await self.app(scope, receive, send)
            return
        if any(key.lower() == b"a2a-version" for key, _ in scope.get("headers", [])):
            await self.app(scope, receive, send)
            return

        body = b""
        more = True
        while more:
            message = await receive()
            body += message.get("body", b"")
            more = message.get("more_body", False)
        try:
            method = json.loads(body or b"{}").get("method", "")
        except (TypeError, ValueError):
            method = ""
        version = "0.3" if "/" in method else PROTOCOL_VERSION
        scope = dict(scope)
        scope["headers"] = [*scope.get("headers", []), (b"a2a-version", version.encode())]

        async def replay():
            return {"type": "http.request", "body": body, "more_body": False}

        await self.app(scope, replay, send)


def create_app(
    *,
    agent_executor: AgentExecutor | None = None,
    agent_instance: Agent | None = None,
    roost_bridge: RoostBridge | None = None,
    task_store: TaskStore | None = None,
) -> Starlette:
    """Build the ASGI app.

    `agent_instance`/`agent_executor`/`roost_bridge`/`task_store` are injection
    points for tests. The task store is built here from the environment: a
    durable SQLite database under `AGENT_STATE_DIR`, so a session's history
    survives a Watchtower recreate. If it cannot be built the agent falls back to
    the in-memory store and still serves (fail-open). The roost bridge is built
    from the environment here too; with no `ROOST_HUB_URL` it is a no-op, and the
    agent serves exactly as before.
    """
    # Persist task/session state. `build_task_store` returns None (rather than
    # raising) when SQLAlchemy is unavailable, so the fallback keeps the agent up.
    store = task_store if task_store is not None else build_task_store(AGENT_NAME)
    if store is None:
        store = InMemoryTaskStore()
    # One reader over the same store the A2A handler writes, so roost answers
    # from the server's own session state rather than a second transcript store.
    history = TaskHistory(store)

    bridge = (
        roost_bridge
        if roost_bridge is not None
        else RoostBridge.from_env(agent_name=AGENT_NAME, history=history)
    )
    card = build_agent_card(
        name=AGENT_NAME,
        description=AGENT_DESCRIPTION,
        url=CARD_URL,
        protocol_version=PROTOCOL_VERSION,
        skills=AGENT_SKILLS,
    )
    executor = agent_executor or TicketAgentExecutor(
        agent, bridge, interpreter=interpreter, jev=jev_client
    )
    request_handler = DefaultRequestHandler(
        agent_executor=executor,
        task_store=store,
        agent_card=card,
    )
    inner_agent = agent_instance if agent_instance is not None else agent

    @asynccontextmanager
    async def lifespan(_app: Starlette):
        async with inner_agent:
            await _register()
            # Bound the store's growth once, at startup. Fail-open: a sweep
            # problem must not stop the agent serving.
            try:
                await history.retention_sweep()
            except Exception as exc:
                print(f"[history] retention sweep skipped: {exc!r}", flush=True)
            # Dial the roost hub alongside the A2A server. `start` returns
            # immediately and connection failures are retried in the background,
            # so a hub outage never delays or breaks startup (fail-open).
            await bridge.start()
            try:
                yield
            finally:
                await bridge.stop()

    return Starlette(
        routes=[
            *create_agent_card_routes(card),
            # v0.3 compatibility keeps the legacy `message/send` dialect working
            # on the same endpoint, so a caller that reads the card as 0.3 is not
            # locked out. The native 1.0 path is what the card advertises.
            *create_jsonrpc_routes(request_handler, rpc_url="/", enable_v0_3_compat=True),
            Route("/healthz", healthz),
        ],
        middleware=[Middleware(A2AVersionHeaderMiddleware)],
        lifespan=lifespan,
    )


app = create_app()
